begin;
-- Optional event trigger generated by the project's automatic-RLS setting.
-- Database owner keeps using it; mobile clients have no reason to execute it.
do $$ begin
  if to_regprocedure('public.rls_auto_enable()') is not null then
    revoke all on function public.rls_auto_enable() from public,anon,authenticated;
  end if;
end $$;
commit;
